      text: "p\nn/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/operator/CasesTab.tsx\n\nimport type { Person } from '../../../src/types';\nimport type { AnyRecord } from '../../lib/api';\nimport CaseDetail from './CaseDetail';\nimport CaseList from './CaseList';\n\nexport default function CasesTab({\n  name,\n  dashboard,\n  people,\n  selectedCase,\n  brief,\n  busy,\n  onOpen,\n  onClose,\n  onReconcile,\n  onDraft,\n}: {\n  name: string;\n  dashboard: AnyRecord;\n  people: Person[];\n  selectedCase: AnyRecord | null;\n  brief: AnyRecord | null;\n  busy: boolean;\n  onOpen: (id: string) => void;\n  onClose: () => void;\n  onReconcile: (intentId: string) => void;\n  onDraft: () => void;\n}) {\n  return (\n    <>\n      <div className=\"page-heading\">\n        <div>\n          <div className=\"eyebrow\">CUSTOMER SUPPORT</div>\n          <h1>Every case, a person.</h1>\n          <p>Hello, {name.split(' ')[0]}. Here are your customer support cases.</p>\n        </div>\n        <div className=\"case-count\">\n          <strong>\n            {dashboard.incidents?.filter((c: AnyRecord) => c.status === 'open').length || 0}\n          </strong>\n          <span>open cases</span>\n        </div>\n      </div>\n      <div className=\"operator-grid\">\n        <CaseList\n          incidents={dashboard.incidents}\n          people={people}\n          selectedId={selectedCase?.incident.id}\n          onOpen={onOpen}\n        />\n        <CaseDetail\n          selectedCase={selectedCase}\n          brief={brief}\n          busy={busy}\n          onClose={onClose}\n          onReconcile={onReconcile}\n          onDraft={onDraft}\n        />\n      </div>\n    </>\n  );\n}\n ?(\n\n:n/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/operator/CasesTab.tsxB\n\nVcall-2d333375-8456-4e65-bbf8-406dd568ec04-64\nfc_ace6eed1-74fd-9874-8fbf-bb3e404eda0a_4",
