      text: 'j\nh/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/TransferTab.tsx\n\nimport type { AnyRecord } from \'../lib/api\';\nimport { money } from \'../lib/format\';\nimport Icon from \'./Icon\';\n\nexport default function TransferTab({\n  dashboard,\n  from,\n  to,\n  amount,\n  concept,\n  busy,\n  setFrom,\n  setTo,\n  setAmount,\n  setConcept,\n  onSubmit,\n  onOverview,\n}: {\n  dashboard: AnyRecord;\n  from: string;\n  to: string;\n  amount: string;\n  concept: string;\n  busy: boolean;\n  setFrom: (v: string) => void;\n  setTo: (v: string) => void;\n  setAmount: (v: string) => void;\n  setConcept: (v: string) => void;\n  onSubmit: () => void;\n  onOverview: () => void;\n}) {\n  return (\n    <>\n      <div className="page-heading">\n        <div>\n          <div className="eyebrow">FROM ONE ACCOUNT TO ANOTHER</div>\n          <h1>Transfers</h1>\n          <p>Send money to another account in this environment.</p>\n        </div>\n      </div>\n      <div className="transfer-layout">\n        <form\n          className="panel transfer-form"\n          onSubmit={(e) => {\n            e.preventDefault();\n            onSubmit();\n          }}\n        >\n          <h2>Your transfer details</h2>\n          <label>\n            From account\n            <select value={from} onChange={(e) => setFrom(e.target.value)} required>\n              {dashboard.accounts?.map((a: AnyRecord) => (\n                <option key={a.id} value={a.id}>\n                  {a.label} · {a.id} · {money(a.balanceCents)}\n                </option>\n              ))}\n            </select>\n          </label>\n          <label>\n            Recipient\n            <select value={to} onChange={(e) => setTo(e.target.value)} required>\n              <option value="">Select an account</option>\n              {dashboard.contacts?.map((a: AnyRecord) => (\n                <option key={a.id} value={a.id}>\n                  {a.name} · {a.label} · {a.id}\n                </option>\n              ))}\n            </select>\n          </label>\n          <label>\n            Amount in euros\n            <div className="amount-input">\n              <input\n                aria-label="Amount in euros"\n                type="number"\n                step="0.01"\n                min="0.01"\n                max="100000"\n                required\n                value={amount}\n                onChange={(e) => setAmount(e.target.value)}\n                placeholder="0.00"\n              />\n              <span>EUR</span>\n            </div>\n          </label>\n          <label>\n            Description\n            <input\n              value={concept}\n              onChange={(e) => setConcept(e.target.value)}\n              placeholder="What is this transfer for?"\n              maxLength={200}\n              required\n            />\n          </label>\n          <button className="primary-button" disabled={busy}>\n            {busy ? \'Processing…\' : \'Send transfer\'}\n            <Icon name="arrow" />\n          </button>\n        </form>\n        <aside className="transfer-note">\n          <Icon name="transfer" />\n          <h2>\n            It is all in\n            <br />\n            your activity.\n          </h2>\n          <p>\n            Check your activity to see the status of your transfers. If you have any questions, the\n            assistant can help.\n          </p>\n          <button className="text-button" onClick={onOverview}>\n            View my accounts ↗\n          </button>\n        </aside>\n      </div>\n    </>\n  );\n}\n z(\n\n:h/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/TransferTab.tsxB\n\nVcall-2d333375-8456-4e65-bbf8-406dd568ec04-63\nfc_ace6eed1-74fd-9874-8fbf-bb3e404eda0a_3',
