      text: "t\nr/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/operator/CopilotBrief.tsx\n\nimport type { AnyRecord } from '../../lib/api';\n\nexport default function CopilotBrief({ brief }: { brief: AnyRecord }) {\n  return (\n    <div className=\"brief\">\n      <p>{brief.summary}</p>\n      {(\n        [\n          ['Verified facts', brief.verifiedFacts],\n          ['Pending checks', brief.pendingChecks],\n          ['Discrepancies', brief.discrepancies],\n          ['Suggested actions', brief.suggestedActions],\n        ] as const\n      ).map(\n        ([label, items]) =>\n          items?.length > 0 && (\n            <div key={label}>\n              <h4>{label}</h4>\n              <ul>\n                {items.map((item: string) => (\n                  <li key={item}>{item}</li>\n                ))}\n              </ul>\n            </div>\n          ),\n      )}\n      {brief.draftReply && (\n        <>\n          <h4>Draft reply</h4>\n          <textarea readOnly rows={6} value={brief.draftReply} />\n          <button\n            className=\"text-button\"\n            onClick={() => navigator.clipboard.writeText(brief.draftReply)}\n          >\n            Copy reply\n          </button>\n        </>\n      )}\n      {brief.sources?.length > 0 && (\n        <p>\n          {brief.sources.map((s: string) => (\n            <span className=\"subtle-tag\" key={s}>\n              {s}\n            </span>\n          ))}\n        </p>\n      )}\n    </div>\n  );\n}\n 3(\n\n:r/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/operator/CopilotBrief.tsxB\n\nVcall-0ec0bab9-7bd8-415e-8f13-cb83f1ea06ee-77\nfc_08ddce59-9c9c-98c7-bb19-3511878fb603_7",
