      text: 'e\nc/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/Notice.tsx\n\nexport default function Notice({\n  error,\n  notice,\n  onDismissError,\n  onDismissNotice,\n}: {\n  error: string;\n  notice: string;\n  onDismissError: () => void;\n  onDismissNotice: () => void;\n}) {\n  return (\n    <>\n      {error && (\n        <div className="alert error" role="alert">\n          {error}\n          <button onClick={onDismissError} aria-label="Dismiss error">\n            ×\n          </button>\n        </div>\n      )}\n      {notice && (\n        <div className="alert notice" role="status">\n          {notice}\n          <button onClick={onDismissNotice} aria-label="Dismiss notice">\n            ×\n          </button>\n        </div>\n      )}\n    </>\n  );\n}\n !(\n\n:c/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/Notice.tsxB\n\nVcall-0ec0bab9-7bd8-415e-8f13-cb83f1ea06ee-76\nfc_08ddce59-9c9c-98c7-bb19-3511878fb603_6',
