      text: "p\nn/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/operator/CaseList.tsx\n\nimport type { Person } from '../../../src/types';\nimport type { AnyRecord } from '../../lib/api';\nimport { date } from '../../lib/format';\n\nexport default function CaseList({\n  incidents,\n  people,\n  selectedId,\n  onOpen,\n}: {\n  incidents: AnyRecord[];\n  people: Person[];\n  selectedId?: string;\n  onOpen: (id: string) => void;\n}) {\n  return (\n    <section className=\"panel case-list\">\n      <div className=\"section-title\">\n        <h2>Inbox</h2>\n        <span className=\"subtle-tag\">All cases</span>\n      </div>\n      {incidents?.map((c: AnyRecord) => (\n        <button\n          key={c.id}\n          className={`case-item ${selectedId === c.id ? 'selected' : ''}`}\n          onClick={() => onOpen(c.id)}\n        >\n          <span\n            className=\"avatar\"\n            style={{ background: people.find((p) => p.id === c.user_id)?.color }}\n          >\n            {people.find((p) => p.id === c.user_id)?.initials}\n          </span>\n          <div>\n            <strong>{people.find((p) => p.id === c.user_id)?.name}</strong>\n            <p>{c.summary}</p>\n            <small>\n              {date(c.created_at)} · {c.status === 'closed' ? 'Resolved' : 'Open'}\n            </small>\n          </div>\n          <span>↗</span>\n        </button>\n      ))}\n    </section>\n  );\n}\n /(\n:n/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/operator/CaseList.tsxB\n\nVcall-0ec0bab9-7bd8-415e-8f13-cb83f1ea06ee-78\nfc_08ddce59-9c9c-98c7-bb19-3511878fb603_8",
