      text: "B\t\nm\nk/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/ApprovalsPanel.tsx\n\nimport type { AnyRecord } from '../lib/api';\nimport { money } from '../lib/format';\n\nexport default function ApprovalsPanel({\n  approvals,\n  accountLabel,\n  contactLabel,\n  onConfirm,\n}: {\n  approvals: AnyRecord[];\n  accountLabel: (id: string) => string;\n  contactLabel: (id: string) => string;\n  onConfirm: (id: string) => void;\n}) {\n  return (\n    <section className=\"panel approvals\">\n      <h2>Proposals awaiting confirmation</h2>\n      {approvals.map((a: AnyRecord) => (\n        <div key={a.id}>\n          <p>\n            <strong>{money(a.payload.amountCents)}</strong> ·{' '}\n            {accountLabel(a.payload.fromAccountId)} → {contactLabel(a.payload.toAccountId)}\n          </p>\n          <p>\n            {a.payload.concept} · Code: <strong>{a.confirmationCode}</strong>\n          </p>\n          <button className=\"primary-button\" onClick={() => onConfirm(a.id)}>\n            Confirm these details\n          </button>\n        </div>\n      ))}\n    </section>\n  );\n}\n #(\n\n:k/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/ApprovalsPanel.tsxB\n\nVcall-0ec0bab9-7bd8-415e-8f13-cb83f1ea06ee-73\nfc_08ddce59-9c9c-98c7-bb19-3511878fb603_3",
