      text: 'f\nd/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/Sidebar.tsx\n\nimport type { AnyRecord } from \'../lib/api\';\nimport Icon from \'./Icon\';\n\nexport default function Sidebar({\n  operator,\n  nav,\n  tab,\n  conversations,\n  conversationId,\n  onNavigate,\n  onNew,\n  onOpen,\n}: {\n  operator: boolean;\n  nav: string[][];\n  tab: string;\n  conversations: AnyRecord[];\n  conversationId: string | null;\n  onNavigate: (id: string) => void;\n  onNew: () => void;\n  onOpen: (id: string) => void;\n}) {\n  return (\n    <aside className="sidebar">\n      <a className="brand" href="/" aria-label="Banana Bank home">\n        <span className="brand-symbol" aria-hidden="true">\n          <svg width="28" height="28" viewBox="0 0 32 32">\n            <path d="M25 4c1 13-7 22-20 20 6 9 25 1 23-16Z" fill="currentColor" />\n            <path d="m24 5 1-3 3 1" fill="none" stroke="currentColor" strokeWidth="2" />\n          </svg>\n        </span>\n        banana<span className="brand-dot">.</span>\n      </a>\n      <div className="workspace-label">{operator ? \'CUSTOMER SUPPORT\' : \'PERSONAL BANKING\'}</div>\n      <nav>\n        {nav.map(([id, icon, label]) => (\n          <button\n            key={id}\n            className={`nav-item ${tab === id ? \'active\' : \'\'}`}\n            onClick={() => onNavigate(id)}\n          >\n            <Icon name={icon} />\n            {label}\n            {id === \'chat\' && <span className="ai-badge">AI</span>}\n          </button>\n        ))}\n      </nav>\n      {!operator && (\n        <>\n          <div className="history-heading">\n            CONVERSATIONS\n            <button aria-label="New conversation" onClick={onNew}>\n              +\n            </button>\n          </div>\n          <div className="conversation-list">\n            {conversations.map((c) => (\n              <button\n                key={c.id}\n                className={conversationId === c.id ? \'selected\' : \'\'}\n                onClick={() => onOpen(c.id)}\n              >\n                <span className="conversation-dot" />\n                {c.title}\n              </button>\n            ))}\n          </div>\n        </>\n      )}\n      <div className="sidebar-bottom">\n        <span className="live-dot" />\n        Demo environment<p>Simulated people and money</p>\n        <span className="banana-mark">banana / LAB</span>\n      </div>\n    </aside>\n  );\n}\n N(\n\n:d/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/app/components/Sidebar.tsxB\n\nVcall-0ec0bab9-7bd8-415e-8f13-cb83f1ea06ee-71\nfc_08ddce59-9c9c-98c7-bb19-3511878fb603_1',
